import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { getJobById, getJobByKey, insertJob, listJobs, openDatabase, toJob, transaction, workerAlive, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 64 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;
const BODY_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function isJsonContentType(header: string | undefined): boolean {
  return header !== undefined && /^application\/json\s*(;|$)/i.test(header.trim());
}

function integerField(body: Record<string, unknown>, name: 'steps' | 'failAttempts', min: number, max: number, fallback: number, errors: FieldError[]): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/** Validates a submission body. Returns the payload with defaults applied, or the field errors. */
function parseSubmission(contentType: string | undefined, text: string, tooLarge: boolean): { payload?: Submission; errors: FieldError[] } {
  if (tooLarge) return { errors: [{ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` }] };
  if (!isJsonContentType(contentType)) return { errors: [{ field: 'body', message: 'Content-Type must be application/json' }] };
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { errors: [{ field: 'body', message: 'malformed JSON' }] };
  }
  if (!isPlainObject(parsed)) return { errors: [{ field: 'body', message: 'must be a JSON object' }] };

  const errors: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!BODY_FIELDS.has(key)) errors.push({ field: key, message: 'unknown field' });
  }
  const input = parsed.input;
  if (typeof input !== 'string') errors.push({ field: 'input', message: 'is required and must be a string' });
  else if (input.length < 1 || input.length > 1000) errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  else if (input.trim() === '') errors.push({ field: 'input', message: 'must not be only whitespace' });

  const steps = integerField(parsed, 'steps', 1, 20, 5, errors);
  const failAttempts = integerField(parsed, 'failAttempts', 0, 5, 0, errors);
  if (errors.length > 0) return { errors };
  return { payload: { input: input as string, steps, failAttempts }, errors };
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let key: string | null = null;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && KEY_PATTERN.test(keyHeader)) key = keyHeader;
    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const parsed = parseSubmission(req.headers['content-type'], text, tooLarge);
  errors.push(...parsed.errors);
  if (errors.length > 0 || !parsed.payload) return invalid(res, errors);
  const payload = parsed.payload;

  const outcome = transaction(db, (): { status: number; row?: JobRow } => {
    if (key !== null) {
      const existing = getJobByKey(db, key);
      if (existing) {
        const same = existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
        return same ? { status: 200, row: existing } : { status: 409 };
      }
    }
    const row = insertJob(db, { id: randomUUID(), ...payload, idempotencyKey: key });
    return { status: 201, row };
  });

  if (outcome.status === 409) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  sendJson(res, outcome.status, toJob(outcome.row!));
}

function notAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined);
  void allow;
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const method = req.method ?? '';

  if (path === '/health') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    return sendJson(res, 200, { status: 'ok', worker: workerAlive(db, Date.now()) ? 'up' : 'down' });
  }
  if (path === '/') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return res.end(uiHtml);
  }
  if (path === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db).map(toJob) });
    if (method === 'POST') return createJob(req, res);
    return notAllowed(res, 'GET, POST');
  }
  const match = JOB_PATH.exec(path);
  if (match) {
    if (method !== 'GET') return notAllowed(res, 'GET');
    let id: string | undefined;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      id = undefined;
    }
    const row = id === undefined ? undefined : getJobById(db, id);
